Tính số đo của $\widehat{A}_{1}$

\choice
{  $86^{\circ} $ }
   { \True  $85^{\circ} $ }
     { $84^{\circ} $  }
    { $87^{\circ} $  }
}{
\begin{tikzpicture}

    % Define the points A, B, C, and D
    \coordinate (A) at (0.4,4);
    \coordinate (B) at (5,2.5);
    \coordinate (C) at (5,0);
    \coordinate (D) at (0,0);
        \coordinate (E) at (0.5,5);
    % Draw the lines
    \draw (A) -- (B) -- (C) -- (D) -- cycle;
    \draw (D) -- (A)--(E);
    \draw (B) -- (C)--(5,4);
    % Add the labels
    \node[above left] at (A) {A};
    \node[below right] at (B) {B};
    \node[below right] at (C) {C};
    \node[below left] at (D) {D};

    % Add angle labels
   % Ghi giá trị góc
    \node at (0.4, 0.3) {$76^\circ$};
    \node at (4.7, 3.0) {$81^\circ$};
    \node at (0.6, 4.2) {$1$};
     % Đánh dấu góc vuông tại điểm E
    \draw (C) rectangle +(-0.3, 0.3);
    \end{tikzpicture}
}
\loigiai{
Ta có $\widehat{ABC} =180^{\circ} -81^{\circ}= 99^{\circ}$\\
Ta có $\widehat{DAB} = 360^{\circ} -76^{\circ}- 90^{\circ}- 99^{\circ}= 95^{\circ}$\\
Vậy $\widehat{A}_{1} = 180^{\circ} - 95^{\circ} =85^{\circ} $
}\end{ex}

